<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class TrainingProgramItem extends Model { protected $fillable=['training_program_id','training_topic_id','title','description','training_type','planned_month','planned_sessions','target_coverage_percentage','planned_date','target_population_type','target_population_description','responsible_employee_id','external_responsible','estimated_duration_minutes','planned_modality','priority','status','annual_work_plan_item_id']; protected $casts=['planned_date'=>'date','target_coverage_percentage'=>'decimal:2']; public function program(){return$this->belongsTo(TrainingProgram::class,'training_program_id');} public function topic(){return$this->belongsTo(TrainingTopic::class,'training_topic_id');} public function needs(){return$this->belongsToMany(TrainingNeed::class,'training_need_program_item');} public function responsible(){return$this->belongsTo(Empleado::class,'responsible_employee_id');} public function annualWorkPlanItem(){return$this->belongsTo(ActividadPlan::class,'annual_work_plan_item_id');} public function sessions(){return$this->hasMany(TrainingSession::class);} }
